package com.candyacademia.spsslite;
import javax.swing.*;import java.awt.*;import java.awt.geom.RoundRectangle2D;import java.util.*;import java.util.List;
public final class ChartPanel extends JPanel{
 private static final long serialVersionUID=1L;private final double[] data;private final String title;
 public ChartPanel(String title,List<Double> values){this.title=title;data=values.stream().mapToDouble(Double::doubleValue).toArray();setPreferredSize(new Dimension(820,500));setBackground(AppTheme.BG);setBorder(BorderFactory.createEmptyBorder(22,22,22,22));}
 protected void paintComponent(Graphics g){super.paintComponent(g);Graphics2D q=(Graphics2D)g.create();q.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);q.setColor(AppTheme.CARD);q.fill(new RoundRectangle2D.Double(22,22,getWidth()-44,getHeight()-44,22,22));q.setColor(AppTheme.HEADING);q.setFont(new Font(Font.SANS_SERIF,Font.BOLD,21));q.drawString("Distribution overview",52,65);q.setColor(AppTheme.MUTED);q.setFont(new Font(Font.SANS_SERIF,Font.BOLD,13));q.drawString(title+"  •  Histogram",52,88);if(data.length==0){q.drawString("No numeric observations are available.",52,130);q.dispose();return;}double min=Arrays.stream(data).min().orElse(0),max=Arrays.stream(data).max().orElse(1);int bins=Math.max(5,Math.min(18,(int)Math.ceil(Math.sqrt(data.length))));int[] count=new int[bins];for(double v:data){int i=max==min?0:Math.min(bins-1,(int)((v-min)/(max-min)*bins));count[i]++;}int left=74,top=120,w=getWidth()-126,h=getHeight()-205,peak=Arrays.stream(count).max().orElse(1),bw=Math.max(1,w/bins);q.setColor(AppTheme.BORDER);for(int i=0;i<=4;i++)q.drawLine(left,top+i*h/4,left+w,top+i*h/4);for(int i=0;i<bins;i++){int bh=(int)((double)count[i]/peak*h);q.setPaint(new GradientPaint(0,top+h-bh,AppTheme.CYAN,0,top+h,AppTheme.BLUE));q.fillRoundRect(left+i*bw+2,top+h-bh,Math.max(3,bw-5),bh,8,8);}q.setColor(AppTheme.MUTED);q.drawString(String.format("%.3f",min),left,top+h+25);q.drawString(String.format("%.3f",max),left+w-45,top+h+25);q.drawString("Observations: "+data.length,left,top+h+52);q.dispose();}
}
